def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    done: dict[tuple[str, str], str] = {}
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in done:
            return done[ref]
        if ref in active:
            raise InterpolationError(f"cycle at {section}:{key}")
        if section not in sections:
            raise InterpolationError(f"no section {section!r}")
        if key not in sections[section]:
            raise InterpolationError(f"no key {key!r} in section {section!r}")
        active.add(ref)
        value = sections[section][key]
        out = []
        i = 0
        while i < len(value):
            if value.startswith("$$", i):
                out.append("$")
                i += 2
                continue
            end = value.find("}", i + 2) if value.startswith("${", i) else -1
            if end < 0:
                out.append(value[i])
                i += 1
                continue
            target, colon, name = value[i + 2:end].rpartition(":")
            out.append(resolve(target if colon else section, name.lower()))
            i = end + 1
        active.discard(ref)
        done[ref] = "".join(out)
        return done[ref]

    return {
        section: {key: resolve(section, key) for key in keys}
        for section, keys in sections.items()
    }

